// Cadena if / else if / else
if (health <= 0)
{
    Die();
}
else if (health < 25)
{
    PlayLowHealthSound();
}
else
{
    // salud normal
}

// Operador ternario: condicion ? valorSiTrue : valorSiFalse
string status = (health > 0) ? "Vivo" : "Muerto";
int damage = isCritical ? baseDamage * 2 : baseDamage;

// If anidado
if (isGrounded)
{
    if (Input.GetKeyDown(KeyCode.Space))
    {
        Jump();
    }
}

// Con operadores lógicos (equivalente, más limpio)
if (isGrounded && Input.GetKeyDown(KeyCode.Space))
{
    Jump();
}

// OR: actúa si cualquiera es true
if (health <= 0 || fellOffMap)
{
    Respawn();
}

