void Update()
{
    float dist = Vector3.Distance(transform.position, player.position);
    if (dist <= attackRange && isAlive)
    {
        Attack();
    }
}

if (health <= 0)
{
    isDead = true;
    animator.SetTrigger("Death");
    GetComponent<Collider>().enabled = false;
}

if (score >= 90)
    grade = "A";
else if (score >= 80)
    grade = "B";
else if (score >= 70)
    grade = "C";
else
    grade = "F";

